import{_ as t,o,c as r,ag as a}from"./chunks/framework.DQQHyi2x.js";const p=JSON.parse('{"title":"Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"features/permissions.md","filePath":"features/permissions.md"}'),s={name:"features/permissions.md"};function i(n,e,l,d,c,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h1><p>Visual rule builder for controlling which operations Claude Code can perform.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Permissions page lets you define allow, ask, and deny rules using pattern matching. Rules control tool access at both user and project levels.</p><h2 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to Use&quot;">​</a></h2><h3 id="viewing-rules" tabindex="-1">Viewing Rules <a class="header-anchor" href="#viewing-rules" aria-label="Permalink to &quot;Viewing Rules&quot;">​</a></h3><p>Rules are organized in three tabs:</p><ul><li><strong>Allow</strong> — operations Claude can perform automatically</li><li><strong>Ask</strong> — operations that require user confirmation</li><li><strong>Deny</strong> — operations that are blocked entirely</li></ul><p>Each rule shows its pattern (e.g., <code>Bash(npm run *)</code>), scope badge, and type hints.</p><h3 id="creating-rules" tabindex="-1">Creating Rules <a class="header-anchor" href="#creating-rules" aria-label="Permalink to &quot;Creating Rules&quot;">​</a></h3><p>Click <strong>&quot;Add Rule&quot;</strong> on any tab to open the rule builder:</p><ol><li><strong>Type</strong> — select Allow, Ask, or Deny</li><li><strong>Tool</strong> — choose the tool (Bash, Read, Write, WebFetch, MCP, Task, Skill, etc.)</li><li><strong>Pattern</strong> — enter an argument pattern with wildcards</li><li><strong>Scope</strong> — set user (global) or project (per-project)</li></ol><p>Quick pattern buttons provide common presets for each tool.</p><h3 id="pattern-syntax" tabindex="-1">Pattern Syntax <a class="header-anchor" href="#pattern-syntax" aria-label="Permalink to &quot;Pattern Syntax&quot;">​</a></h3><p>Rules use <code>Tool(pattern)</code> format with glob wildcards:</p><table tabindex="0"><thead><tr><th>Pattern</th><th>Matches</th></tr></thead><tbody><tr><td><code>Bash</code></td><td>All Bash commands</td></tr><tr><td><code>Bash(npm run *)</code></td><td>Any npm run command</td></tr><tr><td><code>Read(*.env)</code></td><td>Reading .env files</td></tr><tr><td><code>Write(/tmp/*)</code></td><td>Writing to /tmp/</td></tr><tr><td><code>WebFetch(domain:*.anthropic.com)</code></td><td>Fetching from Anthropic domains</td></tr><tr><td><code>MCP(server:postgres:*)</code></td><td>All tools from postgres MCP server</td></tr><tr><td><code>Task(explore)</code></td><td>Explore subagent only</td></tr><tr><td><code>Skill(skill-name)</code></td><td>Specific skill</td></tr></tbody></table><h3 id="evaluation-order" tabindex="-1">Evaluation Order <a class="header-anchor" href="#evaluation-order" aria-label="Permalink to &quot;Evaluation Order&quot;">​</a></h3><p>Rules are evaluated with deny taking highest priority:</p><ol><li><strong>Deny</strong> rules checked first — if matched, operation is blocked</li><li><strong>Ask</strong> rules checked next — if matched, user is prompted</li><li><strong>Allow</strong> rules checked last — if matched, operation proceeds</li><li>If no rules match, the <strong>default mode</strong> applies</li></ol><h3 id="permission-settings" tabindex="-1">Permission Settings <a class="header-anchor" href="#permission-settings" aria-label="Permalink to &quot;Permission Settings&quot;">​</a></h3><p>The settings card provides:</p><ul><li><strong>Default Permission Mode</strong> — <code>default</code> (ask by default), <code>dontAsk</code> (allow by default), or <code>conservative</code> (deny by default)</li><li><strong>Disable Bypass Mode</strong> — prevents using <code>--dangerously-skip-permissions</code></li><li><strong>Additional Allowed Directories</strong> — paths outside the project that Claude can access</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Scope</th></tr></thead><tbody><tr><td><code>~/.claude/settings.json</code> → <code>permissions</code></td><td>User rules</td></tr><tr><td><code>.claude/settings.json</code> → <code>permissions</code></td><td>Project rules</td></tr></tbody></table><p>Rules are stored as arrays under <code>allow</code>, <code>ask</code>, and <code>deny</code> keys.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Start with <strong>deny rules</strong> for sensitive operations, then add specific allow rules.</li><li>Use <strong>domain filtering</strong> on WebFetch to restrict which sites Claude can access.</li><li><strong>Project-level rules</strong> extend (don&#39;t replace) user-level rules.</li><li>The <strong>conservative</strong> default mode blocks everything not explicitly allowed — good for sensitive projects.</li></ul>',27)])])}const g=t(s,[["render",i]]);export{p as __pageData,g as default};
